const props=defineProps({event:{type:Object,required:true},options:{type:Object,required:true},format:{type:String,default:'story'},image:String,index:{type:Number,default:0},total:{type:Number,default:1},editable:Boolean,selected:{type:String,default:''}})
const tiktok=computed(()=>props.options.tiktok&&props.format==='story')
const positionKey=computed(()=>tiktok.value?'story-tiktok':props.format)
