function editAttrs(key){const pos=props.options.positions?.[positionKey.value]?.[key]||{x:0,y:0};return {style:['frame','image'].includes(key)?{}:{translate:pos.x+'px '+pos.y+'px'},'data-inv-edit':key,...(props.editable?{'data-inv-selected':props.selected===key,tabindex:['frame','image'].includes(key)?-1:0,role:['frame','image'].includes(key)?undefined:'button','aria-label':'Editar '+editLabels[key],'aria-pressed':props.selected===key}:{})}}
