function measureArt(){const hero=root.value?.querySelector('.inv-hero');if(hero&&(heroSize.value.width!==hero.clientWidth||heroSize.value.height!==hero.clientHeight))heroSize.value={width:hero.clientWidth,height:hero.clientHeight}}
function imageLoaded(event){naturalSize.value={width:event.target.naturalWidth||1080,height:event.target.naturalHeight||1920};measureArt()}
const artStyle=computed(()=>{const n=naturalSize.value,h=heroSize.value,fit=props.options.imageFit==='contain'?Math.min(h.width/n.width,h.height/n.height):Math.max(h.width/n.width,h.height/n.height),zoom=(Number(props.options.imageZoom)||100)/100,w=n.width*fit*zoom,height=n.height*fit*zoom;return {inset:'auto',width:w+'px',height:height+'px',left:(h.width-w)*(Number(props.options.imagePosition??50)/100)+'px',top:(h.height-height)*(Number(props.options.imagePositionY??50)/100)+'px'}})
let drag=null,pendingTap=null,suppressClick=false,resizeObserver
const movable=key=>key&&!['frame','image'].includes(key)
function savePosition(key,x,y){emit('update',{positions:{...props.options.positions,[positionKey.value]:{...props.options.positions?.[positionKey.value],[key]:{x:Math.round(x),y:Math.round(y)}}}})}
function pointerDown(event){if(!props.editable||event.button!==0)return;const target=event.target.closest('[data-inv-edit]'),key=target?.dataset.invEdit;if(!movable(key))return;const r=root.value.getBoundingClientRect(),b=target.getBoundingClientRect(),scale=r.width/1080,pos=props.options.positions?.[positionKey.value]?.[key]||{x:0,y:0};drag={key,id:event.pointerId,startX:event.clientX,startY:event.clientY,x:pos.x,y:pos.y,scale,moved:false,cx:(b.left+b.width/2-r.left)/scale,cy:(b.top+b.height/2-r.top)/scale,height:r.height/scale,minX:pos.x-(b.left-r.left)/scale,maxX:pos.x+(r.right-b.right)/scale,minY:pos.y-(b.top-r.top)/scale,maxY:pos.y+(r.bottom-b.bottom)/scale};root.value.setPointerCapture(event.pointerId)}
function pointerMove(event){if(!drag||event.pointerId!==drag.id)return;const dx=event.clientX-drag.startX,dy=event.clientY-drag.startY;if(!drag.moved&&Math.hypot(dx,dy)<5)return;drag.moved=true;event.preventDefault();let x=Math.max(drag.minX,Math.min(drag.maxX,drag.x+dx/drag.scale)),y=Math.max(drag.minY,Math.min(drag.maxY,drag.y+dy/drag.scale));const centerX=drag.cx+x-drag.x,centerY=drag.cy+y-drag.y,snapX=Math.abs(centerX-540)<10/drag.scale,snapY=Math.abs(centerY-drag.height/2)<10/drag.scale;if(snapX)x+=540-centerX;if(snapY)y+=drag.height/2-centerY;guides.value={x:snapX,y:snapY};savePosition(drag.key,x,y)}
