function keyboardMove(event){if(!props.editable||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;const key=event.target.closest('[data-inv-edit]')?.dataset.invEdit;if(!movable(key))return;event.preventDefault();event.stopPropagation();const p=props.options.positions?.[positionKey.value]?.[key]||{x:0,y:0},step=event.shiftKey?10:2;savePosition(key,p.x+(event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0),p.y+(event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0))}
async function fitTitle(){await nextTick();if(!root.value)return;const title=root.value.querySelector('h2'),heading=root.value.querySelector('.inv-heading'),hero=root.value.querySelector('.inv-hero'),top=root.value.querySelector('.inv-topline');if(!title)return;const base=(props.options.titleSize||84)*(tiktok.value?.82:props.format==='square'?.68:props.format==='portrait'?.82:1);title.style.fontSize=base+'px';const available=tiktok.value?Math.max(70,260-(heading.offsetHeight-title.offsetHeight)):Math.max(60,hero.clientHeight-(top.offsetTop+top.offsetHeight+30)-(heading.offsetHeight-title.offsetHeight)-14);let size=base;while(title.scrollHeight>available&&size>26){size-=2;title.style.fontSize=size+'px'}}
