<template>
 <article ref="root" @pointerdown="pointerDown" @pointermove="pointerMove" @pointerup="pointerUp" @pointercancel="pointerUp" @lostpointercapture="pointerUp" @keydown.capture="keyboardMove" class="event-invitation" :class="{'is-editable':editable}" @click="choose" @keydown="choose" :data-invitation-format="format" :data-social-margins="options.socialMargins!==false?'true':null" :data-status="status.id" :data-layout="options.layout || 'full'" :data-tiktok="tiktok?'true':null" :style="[{'--inv-a':palette[0],'--inv-b':palette[1],'--inv-c':palette[2],'--inv-title':options.titleSize+'px','--inv-position':options.imagePosition+'%','--inv-brightness':options.imageBrightness+'%'},customStyle]">
